<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Composition with Red, Blue and Yellow (1930) | Piet Mondrian</title>
<meta name="description" content="Piet Mondrian, Composition with Red, Blue and Yellow, 1930. De Stijl, Neoplasticism and why the painting matters.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;600;900&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#d8261c; --blue:#1f3f99; --yellow:#f4d21f;
    --white:#f7f5ef; --grey:#cfccc4; --black:#111;
    --line:clamp(8px,1.4vw,16px);
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html{background:var(--black)}
  body{font-family:"Archivo",system-ui,sans-serif;color:var(--black);background:var(--black);line-height:1.5}
  a{color:inherit}
  :focus-visible{outline:4px solid var(--yellow);outline-offset:3px}
  .skip{position:absolute;left:-999px;top:0;background:var(--yellow);padding:.5rem 1rem;z-index:10}
  .skip:focus{left:1rem}
  /* The whole page is one grid of white fields; the grid gap is the black line */
  .grid{display:grid;gap:var(--line);padding:var(--line);padding-bottom:0;background:var(--black)}
  footer.grid{padding-bottom:var(--line)}
  .cell{background:var(--white);padding:clamp(1.25rem,3vw,2.5rem)}
  .red{background:var(--red);color:var(--white)}
  .blue{background:var(--blue);color:var(--white)}
  .yellow{background:var(--yellow)}
  .grey{background:var(--grey)}
  h1,h2{font-weight:900;letter-spacing:-.02em;line-height:1}
  h1{font-size:clamp(2.4rem,6.5vw,5.6rem)}
  h2{font-size:clamp(1.5rem,3vw,2.4rem);margin-bottom:.75rem}
  .kicker{font-weight:600;text-transform:uppercase;letter-spacing:.14em;font-size:.8rem;margin-bottom:1rem}
  p{max-width:38rem;font-size:clamp(1rem,1.2vw,1.15rem)}
  p+p{margin-top:.8rem}

  /* HERO */
  .hero{grid-template-columns:1.25fr 1fr;min-height:100vh}
  .hero .title{display:flex;flex-direction:column;justify-content:space-between;gap:2rem}
  .hero .byline{font-size:clamp(1.1rem,1.8vw,1.5rem);font-weight:600}
  .stage{position:relative;padding:0;background:var(--black);min-height:60vh;display:grid;place-items:center;overflow:hidden}
  .stage canvas{position:absolute;inset:0;width:100%;height:100%;display:block}
  /* CSS fallback schematic, drawn only from the fact sheet description; three.js replaces it when it loads */
  .painting{width:min(100%,80vh);aspect-ratio:1/1;display:grid;gap:var(--line);background:var(--black);
    grid-template-columns:1fr 3.2fr;grid-template-rows:1.4fr 1.4fr 1fr;
    grid-template-areas:"w1 red" "w2 red" "blue r2"}
  .painting i{background:var(--white);display:block}
  .painting .p-red{grid-area:red;background:var(--red)}
  .painting .p-blue{grid-area:blue;background:var(--blue)}
  .painting .p-w1{grid-area:w1}.painting .p-w2{grid-area:w2}
  .painting .p-r2{grid-area:r2;display:grid;gap:var(--line);background:var(--black);grid-template-columns:5fr 1fr;grid-template-rows:2fr 1fr}
  .painting .p-r2 .p-yellow{background:var(--yellow);grid-column:2;grid-row:2}
  .painting .p-r2 .p-tall{grid-row:1/3}
  .stage.has-3d .painting{visibility:hidden}
  .stage figcaption{position:absolute;left:0;bottom:0;background:var(--white);font-size:.8rem;padding:.4rem .7rem;z-index:2}

  /* FACTS */
  .facts{grid-template-columns:repeat(4,1fr)}
  .fact .k{font-size:.75rem;text-transform:uppercase;letter-spacing:.14em;font-weight:600}
  .fact .v{font-size:clamp(1.2rem,2vw,1.7rem);font-weight:900;line-height:1.15;margin-top:.4rem}

  /* STORY */
  .story{grid-template-columns:2fr 1fr 1fr}
  .story .wide{grid-row:span 2}
  .story .span2{grid-column:span 2}
  ul.rules{list-style:none;display:grid;gap:.6rem;margin-top:1rem}
  ul.rules li{display:flex;gap:.75rem;align-items:center;font-weight:600}
  .sw{width:1.4rem;height:1.4rem;border:3px solid var(--black);flex:none}
